export class VaultV2Adapter {
    type;
    address;
    parentVault;
    adapterId;
    skimRecipient;
    constructor({ type, address, parentVault, adapterId, skimRecipient, }) {
        this.type = type;
        this.address = address;
        this.parentVault = parentVault;
        this.adapterId = adapterId;
        this.skimRecipient = skimRecipient;
    }
}
